import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int numerator = scanner.nextInt();
        int denominator = scanner.nextInt();
        int max_iter = scanner.nextInt();
        double ratio_x_over_y = (double) numerator / denominator;
        double target_ratio = 1 + ratio_x_over_y;
        double min_diff = 1.0; // initialize with a large value
        int best_num = 0;
        int best_den = 1;

        for (int i = 1; i <= max_iter; i++) {
            double val1 = (double) ((int) (ratio_x_over_y * i)) / i;
            double current_diff = Math.abs(val1 - ratio_x_over_y);
            if (current_diff < min_diff) {
                min_diff = current_diff;
                best_num = (int) (ratio_x_over_y * i);
                best_den = i;
            }
            double val2 = (double) ((int) (ratio_x_over_y * i + 1)) / i;
            current_diff = Math.abs(val2 - ratio_x_over_y);
            if (current_diff < min_diff) {
                min_diff = current_diff;
                best_num = (int) (ratio_x_over_y * i) + 1;
                best_den = i;
            }
        }
        System.out.println(best_num + "/" + best_den);
        scanner.close();
    }
}
